function dw_meta(string $page): void {
    echo '<input type="hidden" name="_csrf" value="'.dw_h(dw_csrf_token()).'"><input type="hidden" name="return_page" value="'.dw_h($page).'">';
    if ($page === 'wingo') {
        $returnGame = dw_wingo_return_game((string)($_GET['game'] ?? ''));
        if ($returnGame !== '') echo '<input type="hidden" name="return_game" value="'.dw_h($returnGame).'">';
    }
}
function dw_badge(string $status): string {
    $s=strtolower($status);$class=in_array($s,['approved','payed','active','success','received','answered','resolved','completed','pass'],true)?'':(in_array($s,['pending','wait','pendingreview','processing','reviewing','open'],true)?'warn':(in_array($s,['rejected','cancel','disabled','failed','suspended','critical'],true)?'danger':'gray'));
    return '<span class="badge '.$class.'">'.dw_h($status).'</span>';
}
function dw_pages(int $total,int $size,int $current,array $query): void {
    $count=(int)ceil($total/max(1,$size));if($count<=1)return;echo '<nav class="pagination">';
    $start=max(1,$current-2);$end=min($count,$current+2);
    if($current>1){$query['p']=$current-1;echo '<a href="?'.dw_h(http_build_query($query)).'">‹</a>';}
    for($i=$start;$i<=$end;$i++){$query['p']=$i;echo '<a class="'.($i===$current?'active':'').'" href="?'.dw_h(http_build_query($query)).'">'.$i.'</a>';}
    if($current<$count){$query['p']=$current+1;echo '<a href="?'.dw_h(http_build_query($query)).'">›</a>';}echo '</nav>';
}

/**
 * FIXED: Display wallet/bank details for withdrawals.
 * Handles JSON snapshots, direct columns, and various field naming conventions.
 */
function dw_wallet_display(array $row): string {
    // Submitted snapshot is authoritative; use the linked account for legacy rows.
    $snapshot=json_decode((string)($row['wallet_snapshot']??''),true);
    if (!$snapshot && !empty($row['wallet_id'])) {
        $c=db();
        if($c){$q=$c->prepare('SELECT * FROM withdraw_wallets WHERE id=? AND user_id=? LIMIT 1');
            if($q){$wid=(int)$row['wallet_id'];$uid=(int)$row['user_id'];$q->bind_param('ii',$wid,$uid);$q->execute();$wallet=$q->get_result()->fetch_assoc();
                if($wallet){$details=json_decode((string)($wallet['wallet_data']??''),true)?:[];$row['wallet_snapshot']=json_encode(array_merge($wallet,$details));}
            }
        }
    }
    return mw_withdraw_account_html($row);
    /* Legacy parser retained below for compatibility with older snapshots. */
    // First try to decode JSON from wallet_snapshot or wallet_info
    $json = '';
    if (!empty($row['wallet_snapshot'])) {
        $json = (string)$row['wallet_snapshot'];
    } elseif (!empty($row['wallet_info'])) {
        $json = (string)$row['wallet_info'];
    }
    
    $data = [];
    if ($json !== '') {
        $decoded = json_decode($json, true);
        if (is_array($decoded)) {
            $data = $decoded;
        }
    }
    
    // If no JSON data, check direct columns on the withdrawal row
    if (empty($data)) {
        $directFields = [
            'bank_name', 'bankName', 'bank', 'wallet_name', 'walletName',
            'account_no', 'accountNo', 'account_number', 'accountNumber',
            'upi_id', 'upiId', 'usdt_address', 'usdtAddress',
            'ifsc_code', 'ifscCode', 'ifsc', 'holder_name', 'holderName',
            'account_holder', 'accountHolder', 'payee_name', 'payeeName',
            'branch', 'bank_branch', 'bankBranch'
        ];
        foreach ($directFields as $field) {
            if (!empty($row[$field])) {
                $data[$field] = $row[$field];
            }
        }
    }
    
    // Also check top-level fields in decoded JSON for common aliases
    if (!empty($data)) {
        $account = '';
        $name = '';
        
        // Account number / UPI / USDT address
        foreach (['accountNo', 'account_no', 'accountNumber', 'account_number', 'upiId', 'upi_id', 'usdtAddress', 'usdt_address', 'walletAddress', 'wallet_address'] as $k) {
            if (!empty($data[$k])) { $account = (string)$data[$k]; break; }
        }
        
        // Bank / wallet name
        foreach (['bankName', 'bank_name', 'bank', 'walletName', 'wallet_name', 'wallet'] as $k) {
            if (!empty($data[$k])) { $name = (string)$data[$k]; break; }
        }
        
        // IFSC code
        $ifsc = '';
        foreach (['ifscCode', 'ifsc_code', 'ifsc', 'IFSC'] as $k) {
            if (!empty($data[$k])) { $ifsc = (string)$data[$k]; break; }
        }
        
        // Holder name
        $holder = '';
        foreach (['holderName', 'holder_name', 'accountHolder', 'account_holder', 'payeeName', 'payee_name', 'name'] as $k) {
            if (!empty($data[$k])) { $holder = (string)$data[$k]; break; }
        }
        
        // Build output
        $out = '';
        if ($name !== '') {
            $out .= dw_h($name);
        }
        if ($holder !== '' && $holder !== $name) {
            $out .= ($out !== '' ? ' · ' : '') . dw_h($holder);
        }
        if ($account !== '') {
            $out .= ($out !== '' ? ' ' : '') . '<span class="mono">' . dw_h(dw_mask_account($account)) . '</span>';
        }
        if ($ifsc !== '') {
            $out .= '<div class="small mono">IFSC: ' . dw_h($ifsc) . '</div>';
        }
        
        if ($out !== '') {
            return $out;
        }
    }
    
    // Fallback: if there's a plain string in wallet_snapshot/wallet_info, mask it
    if ($json !== '' && !is_array(json_decode($json, true))) {
        return dw_h(dw_mask_account($json));
    }
    
    // Last resort: show method if available
    if (!empty($row['method'])) {
        return '<span class="muted">' . dw_h((string)$row['method']) . ' — no account details</span>';
    }
    
    return '<span class="muted">No account details</span>';
}

if (!empty($_GET['export'])) {
    $export=(string)$_GET['export'];$rows=[];$headers=[];$filename='maanwin-'.$export.'-'.date('Ymd-His').'.csv';
    if($export==='users'){dw_require_permission($permissions,'users');$headers=['ID','Username','Mobile','Nickname','Balance','VIP','Status','Created'];foreach(dw_rows($conn,"SELECT id,username,mobile,nickname,balance,vip_level,status,created_at FROM users WHERE role='user' ORDER BY id DESC LIMIT 10000") as $r)$rows[]=[(int)$r['id'],$r['username'],$r['mobile'],$r['nickname'],$r['balance'],$r['vip_level'],$r['status'],$r['created_at']];}
    elseif($export==='recharges'){dw_require_permission($permissions,'recharges');$headers=['Order','User','Amount','Gift','Type','Status','UTR','Created'];foreach(dw_rows($conn,"SELECT r.*,u.username FROM recharge_orders r LEFT JOIN users u ON u.id=r.user_id ORDER BY r.id DESC LIMIT 10000") as $r)$rows[]=[$r['order_no'],$r['username'],$r['amount'],$r['gift_amount'],$r['recharge_type'],$r['status'],$r['utr'],$r['created_at']];}
    elseif($export==='withdrawals'){dw_require_permission($permissions,'withdrawals');$headers=['Order','User','Amount','Method','Status','Reserved','Note','Created'];foreach(dw_rows($conn,"SELECT w.*,u.username FROM withdraw_requests w LEFT JOIN users u ON u.id=w.user_id ORDER BY w.id DESC LIMIT 10000") as $r)$rows[]=[$r['order_no'],$r['username'],$r['amount'],$r['method'],$r['status'],$r['is_reserved'],$r['admin_note'],$r['created_at']];}
    elseif($export==='ledger'){dw_require_permission($permissions,'finance');$headers=['Record','Order','User','Type','Amount','Before','After','Description','Created'];foreach(dw_rows($conn,"SELECT f.*,u.username FROM financial_records f LEFT JOIN users u ON u.id=f.user_id ORDER BY f.id DESC LIMIT 10000") as $r)$rows[]=[$r['record_no'],$r['order_no'],$r['username'],$r['type'],$r['amount'],$r['balance_before'],$r['back_amount'],$r['description'],$r['created_at']];}
    elseif($export==='audit'){dw_require_permission($permissions,'audit');$headers=['ID','Admin ID','Action','Target','Target ID','IP','Data','Created'];foreach(dw_rows($conn,"SELECT * FROM admin_audit_logs ORDER BY id DESC LIMIT 10000") as $r)$rows[]=[$r['id'],$r['admin_user_id'],$r['action'],$r['target_type'],$r['target_id'],$r['ip'],$r['data_json'],$r['created_at']];}
    else throw new RuntimeException('Unknown export.');
    dw_admin_audit($conn,$admin,'csv_export',$export,0,['rows'=>count($rows)]);
    dw_csv_download($filename,$headers,$rows);
}

